import test from 'node:test';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {mkdtemp, writeFile, rm} from 'node:fs/promises';
import {tmpdir} from 'node:os';
import {fileURLToPath} from 'node:url';
import {testServer} from '../../server/test/helpers.js';

async function scenario(fn) {
  const server = await testServer();
  const directory = await mkdtemp(tmpdir() + '/crew-search-cli-');
  try {
    const api = server.agent();
    await api('POST', '/auth/signup', {name: 'Search CLI', email: 'searchcli@example.test', password: 'correct-horse-battery'});
    const org = (await api('POST', '/orgs', {name: 'CLI search'})).data.organization;
    const project = (await api('POST', '/orgs/' + org.id + '/projects', {key: 'CLI', name: 'CLI search project'})).data.project;
    const token = (await api('POST', '/tokens', {name: 'CLI', scopes: ['*']})).data.token;
    await writeFile(directory + '/config.json', JSON.stringify({url: server.url, token}), {mode: 0o600});
    const cli = args => new Promise((resolve, reject) => {
      const child = spawn(process.execPath, [fileURLToPath(new URL('../bin/crew.js', import.meta.url)), ...args, '--config', directory + '/config.json', '--json']);
      let stdout = '', stderr = '';
      const timer = setTimeout(() => {child.kill('SIGKILL'); reject(new Error('CLI deadline exceeded'));}, 10000);
      child.stdout.on('data', value => stdout += value);
      child.stderr.on('data', value => stderr += value);
      child.on('error', error => {clearTimeout(timer); reject(error);});
      child.on('close', code => {
        clearTimeout(timer);
        let data = null;
        try {if (stdout.trim()) data = JSON.parse(stdout);} catch (error) {reject(error); return;}
        resolve({code, data, stdout, stderr});
      });
    });
    await fn({api, org, project, cli, directory});
  } finally {await server.close(); await rm(directory, {recursive: true, force: true});}
}

test('actual token CLI searches compound queries and traverses all cursor pages', () => scenario(async ({api, org, project, cli}) => {
  for (const title of ['Search first', 'Search second', 'Search third']) await api('POST', '/projects/' + project.id + '/issues', {title, priority: 3});
  const result = await cli(['search', '--org', org.id, '--query', 'search AND priority>=3', '--limit', '1', '--all']);
  assert.equal(result.code, 0, result.stderr);
  assert.equal(result.data.items.length, 3);
  assert.equal(result.data.nextCursor, null);
}));
test('actual CLI validates queries locally and gets accessible suggestions', () => scenario(async ({cli, org}) => {
  const checked = await cli(['search', 'check', 'assignee:@me AND NOT status:done']);
  assert.equal(checked.code, 0, checked.stderr); assert.equal(checked.data.valid, true);
  assert.equal((await cli(['search', 'check', 'label:'])).code, 1);
  const suggestions = await cli(['search', 'suggest', 'project:', '--org', org.id]);
  assert.equal(suggestions.code, 0, suggestions.stderr);
  assert.equal(suggestions.data.items[0].replacement, 'project:CLI');
}));
test('actual CLI creates edits runs and confirms deletion of saved filters', () => scenario(async ({api, cli, org, project, directory}) => {
  await api('POST', '/projects/' + project.id + '/issues', {title: 'Important', priority: 4});
  await writeFile(directory + '/query.txt', 'priority>=3');
  const created = await cli(['filter', 'create', '--org', org.id, '--name', 'Urgent', '--query-file', directory + '/query.txt']);
  assert.equal(created.code, 0, created.stderr);
  const id = created.data.filter.id;
  assert.equal((await cli(['filter', 'run', id])).data.total, 1);
  const edited = await cli(['filter', 'edit', id, '--name', 'Critical', '--query', 'priority>=4', '--revision', '1']);
  assert.equal(edited.code, 0, edited.stderr); assert.equal(edited.data.filter.revision, 2);
  assert.equal((await cli(['filter', 'edit', id, '--name', 'Stale', '--revision', '1'])).code, 1);
  assert.equal((await cli(['filter', 'delete', id])).code, 1);
  assert.equal((await cli(['filter', 'delete', id, '--yes'])).code, 0);
  assert.equal((await cli(['filter', 'show', id])).code, 1);
}));
test('actual CLI lists saved filters and documents every search family', () => scenario(async ({cli, org}) => {
  await cli(['filter', 'create', '--org', org.id, '--name', 'Everything']);
  const list = await cli(['filter', 'list', '--org', org.id]);
  assert.equal(list.code, 0, list.stderr); assert.equal(list.data.items[0].name, 'Everything');
  const options = await cli(['filter', 'options', '--org', org.id]);
  assert.equal(options.code, 0, options.stderr); assert.equal(options.data.projects.length, 1);
  assert.equal((await cli(['search', '--help'])).code, 0);
  assert.equal((await cli(['filter', '--help'])).code, 0);
}));

import {AppError, savedFilterInput, validatedQuery, integer} from '@crew/shared';
import {searchAccess, validateQueryProjects} from './search.js';

export function publicFilter(row, userId) {
  return {id: row.id, orgId: row.org_id, ownerId: row.owner_id, teamId: row.team_id,
    visibility: row.visibility, name: row.name, description: row.description, query: row.query,
    revision: row.revision, createdAt: row.created_at, updatedAt: row.updated_at, canEdit: row.owner_id === userId};
}

function teamMember(ctx, userId, teamId, orgId) {
  return Boolean(ctx.db.prepare(`SELECT 1 FROM teams t JOIN team_members tm ON tm.team_id=t.id
    WHERE t.id=? AND t.org_id=? AND tm.user_id=?`).get(teamId, orgId, userId));
}

function queryVisible(ctx, row, projectIds) {
  try {
    validateQueryProjects(ctx, validatedQuery(row.query).ast, row.org_id, projectIds);
    return true;
  } catch (error) {
    if (error.code === 'FORBIDDEN') return false;
    throw error;
  }
}

export function canReadFilter(ctx, req, row) {
  if (!ctx.permissions.membership(req.user.id, row.org_id)) return false;
  if (row.visibility === 'personal' && row.owner_id !== req.user.id) return false;
  if (row.visibility === 'team' && !teamMember(ctx, req.user.id, row.team_id, row.org_id)) return false;
  const projectIds = ctx.permissions.projectIds(req.user.id, row.org_id).filter(id => ctx.permissions.canProject(req.user.id, id, 'insight:read'));
  return queryVisible(ctx, row, projectIds);
}

export function getFilter(ctx, req, id, {edit = false} = {}) {
  ctx.permissions.scope(req, edit ? 'insight:write' : 'insight:read');
  const row = ctx.db.prepare('SELECT * FROM saved_filters WHERE id=?').get(id);
  if (!row || !canReadFilter(ctx, req, row)) throw new AppError('NOT_FOUND', 'Saved filter not found', 404);
  if (edit) {
    if (row.owner_id !== req.user.id) throw new AppError('FORBIDDEN', 'Only the filter creator can change it', 403);
    ctx.permissions.assertOrg(req, row.org_id, 'insight:write');
  }
  return publicFilter(row, req.user.id);
}

export function listFilters(ctx, req) {
  const access = searchAccess(ctx, req);
  if (req.query.visibility && !['personal', 'team', 'all'].includes(req.query.visibility)) throw new AppError('VALIDATION', 'Unknown filter visibility', 422, {visibility: 'Choose personal, team or all'});
  const rows = ctx.db.prepare('SELECT * FROM saved_filters WHERE org_id=? ORDER BY updated_at DESC,id').all(access.orgId);
  const items = rows.filter(row => canReadFilter(ctx, req, row))
    .filter(row => !req.query.visibility || req.query.visibility === 'all' || row.visibility === req.query.visibility)
    .filter(row => !req.query.teamId || row.team_id === req.query.teamId)
    .filter(row => req.query.owned !== 'true' || row.owner_id === req.user.id)
    .map(row => publicFilter(row, req.user.id));
  return {...ctx.paginate(items, req.query), total: items.length};
}

function checkFilter(ctx, req, input) {
  ctx.permissions.assertOrg(req, input.orgId, 'insight:write');
  const projects = ctx.permissions.projectIds(req.user.id, input.orgId);
  validateQueryProjects(ctx, validatedQuery(input.query).ast, input.orgId, projects);
  if (input.visibility === 'team') {
    if (!input.teamId || !teamMember(ctx, req.user.id, input.teamId, input.orgId)) throw new AppError('VALIDATION', 'Choose one of your teams in this organization', 422, {teamId: 'Team membership is required to share a filter'});
  } else if (input.teamId) throw new AppError('VALIDATION', 'A personal filter cannot have a team', 422, {teamId: 'Clear the team or choose team visibility'});
}

function uniqueName(ctx, userId, input, exceptId = '') {
  const duplicate = ctx.db.prepare(`SELECT id FROM saved_filters WHERE owner_id=? AND org_id=?
    AND name=? COLLATE NOCASE AND visibility=? AND COALESCE(team_id,'')=COALESCE(?,'') AND id<>?`)
    .get(userId, input.orgId, input.name, input.visibility, input.teamId, exceptId);
  if (duplicate) throw new AppError('CONFLICT', 'You already saved a filter with this name in this destination', 409, {name: 'Choose a distinct name'});
}

function emitFilter(ctx, req, action, before, after) {
  const filter = after ?? before;
  ctx.bus.emit({actorId: req.user.id, orgId: filter.orgId, entityType: 'savedFilter', entityId: filter.id,
    action, before, after, time: ctx.now()});
}

export function createFilter(ctx, req, body) {
  const input = savedFilterInput(body);
  checkFilter(ctx, req, input);
  const id = ctx.id(), now = ctx.now();
  ctx.transaction(() => {
    uniqueName(ctx, req.user.id, input);
    ctx.db.prepare(`INSERT INTO saved_filters(id,org_id,owner_id,team_id,visibility,name,description,query,created_at,updated_at)
      VALUES(?,?,?,?,?,?,?,?,?,?)`).run(id, input.orgId, req.user.id, input.teamId, input.visibility, input.name, input.description, input.query, now, now);
  });
  const filter = publicFilter(ctx.db.prepare('SELECT * FROM saved_filters WHERE id=?').get(id), req.user.id);
  emitFilter(ctx, req, 'created', null, filter);
  return filter;
}

export function updateFilter(ctx, req, id, body) {
  const before = getFilter(ctx, req, id, {edit: true});
  const {expectedRevision, ...changes} = body ?? {};
  const input = {...before, ...savedFilterInput(changes, {partial: true})};
  if (input.orgId !== before.orgId) throw new AppError('VALIDATION', 'A saved filter cannot move organizations', 422, {orgId: 'Create a new filter in the other organization'});
  if (expectedRevision !== undefined && integer(expectedRevision, 'expectedRevision', {min: 1}) !== before.revision) throw new AppError('CONFLICT', 'This filter changed; reload before saving', 409, {expectedRevision: 'The saved revision is newer'});
  checkFilter(ctx, req, input);
  ctx.transaction(() => {
    uniqueName(ctx, req.user.id, input, id);
    ctx.db.prepare('UPDATE saved_filters SET name=?,description=?,query=?,visibility=?,team_id=?,revision=revision+1,updated_at=? WHERE id=?')
      .run(input.name, input.description, input.query, input.visibility, input.teamId, ctx.now(), id);
  });
  const filter = publicFilter(ctx.db.prepare('SELECT * FROM saved_filters WHERE id=?').get(id), req.user.id);
  emitFilter(ctx, req, 'updated', before, filter);
  return filter;
}

export function deleteFilter(ctx, req, id) {
  const before = getFilter(ctx, req, id, {edit: true});
  ctx.db.prepare('DELETE FROM saved_filters WHERE id=?').run(id);
  emitFilter(ctx, req, 'deleted', before, null);
}

import {test} from 'node:test';
import assert from 'node:assert/strict';
import {lexQuery, QuerySyntaxError} from '../src/query/lexer.js';
import {parseQuery, positiveTerms} from '../src/query/parser.js';
import {evaluateQuery} from '../src/query/evaluate.js';
const issue = {key:'APP-1',title:'Repair the Search Index',description:'Quoted phrase and Unicode café',projectId:'p1',projectKey:'APP',statusId:'s1',statusName:'In Progress',statusCategory:'active',priority:3,assigneeId:'u1',labels:[{id:'l1',name:'Urgent'}],createdAt:'2026-10-10T12:00:00.000Z',updatedAt:'2026-10-15T12:00:00.000Z'};
const matches = query => evaluateQuery(parseQuery(query), issue, {userId:'u1'});
test('lexer retains exact offsets and decoded quote escapes', () => {
  const tokens = lexQuery('label:"a\\"b" AND (search)');
  assert.equal(tokens[2].value, 'a"b');
  assert.deepEqual([tokens[2].start,tokens[2].end], [6,12]);
});
test('AND binds before OR and NOT binds before both', () => {
  assert.equal(matches('missing OR search AND NOT missing'), true);
  assert.equal(matches('search OR missing AND missing'), true);
  assert.equal(matches('(search OR missing) AND missing'), false);
});
test('adjacent terms are an implicit conjunction', () => {
  assert.equal(matches('repair ind'), true);
  assert.equal(matches('repair absent'), false);
});
test('quoted phrases match contiguous normalized text', () => {
  assert.equal(matches('"search index"'), true);
  assert.equal(matches('"index search"'), false);
  assert.equal(matches('CAFÉ'), true);
});
test('status accepts exact id, category and quoted name', () => {
  for (const query of ['status:s1','status:active','status:"In Progress"']) assert.equal(matches(query), true);
  assert.equal(matches('status:done'), false);
});
test('assignee resolves current user and unassigned semantics', () => {
  assert.equal(matches('assignee:@me'), true);
  assert.equal(evaluateQuery('assignee:@me',issue,{userId:'other'}), false);
  assert.equal(evaluateQuery('assignee:unassigned',{...issue,assigneeId:null}), true);
});
test('label matches id and exact name without prefix leakage', () => {
  assert.equal(matches('label:urgent'), true);
  assert.equal(matches('label:l1'), true);
  assert.equal(matches('label:urg'), false);
});
test('priority comparison operators use numeric values', () => {
  for(const query of ['priority>=3','priority<=3','priority>2','priority<4','priority=3','priority!=0']) assert.equal(matches(query), true);
  assert.equal(matches('priority>3'), false);
});
test('project accepts id and case-insensitive key', () => {
  assert.equal(matches('project:app'), true);
  assert.equal(matches('project:p1'), true);
  assert.equal(matches('project:other'), false);
});
test('date filters compare UTC instants', () => {
  assert.equal(matches('created>2026-10-09 AND updated<2026-10-16'), true);
  assert.equal(matches('created>=2026-10-11'), false);
  assert.equal(matches('updated="2026-10-15T12:00:00.000Z"'), true);
});
test('empty query includes every issue', () => assert.equal(matches('  '), true));
test('negative terms are excluded from highlight terms', () => assert.deepEqual(positiveTerms(parseQuery('search AND NOT missing')).map(term=>term.value),['search']));
for(const [query,offset] of [['label:',6],['priority>=9',10],['created>2026-02-30',8],['unknown:x',0],['(foo',4],['foo OR',6],['"open',0],['foo)',3],['status>active',6]]) {
  test('positioned syntax error: '+query, () => {
    assert.throws(()=>parseQuery(query), error=>error instanceof QuerySyntaxError && error.offset===offset && error.column===offset+1);
  });
}
test('quoted unknown escape is rejected at the slash',()=>assert.throws(()=>parseQuery('"a\\q"'),error=>error.offset===2));
test('deeply nested malicious input fails with useful error',()=>assert.throws(()=>parseQuery('('.repeat(65)+'x'+')'.repeat(65)),/nesting/));
